-- Cover images for the seeded books.
--
-- Mounted into /docker-entrypoint-initdb.d/ after 03-seed.sql, so this only runs when
-- the booksnap-db-data volume is first created (same caveat as schema.sql and seed.sql).
-- To load it into a database that already exists, run it by hand:
--
--   docker exec -i booksnap-postgres sh -c \
--     'psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" -f -' < server/sql/covers.sql
--
-- Images are medium-size JPEGs from the Open Library Covers API
-- (https://covers.openlibrary.org), keyed by the same ISBN precedence the application
-- uses: ISBN-13 first, ISBN-10 as fallback.

-- Harry Potter and the Sorcerer's Stone
INSERT INTO cover (isbn, image, content_type) VALUES
('9780439708180', decode('', 'base64'), 'image/jpeg')
ON CONFLICT (isbn) DO NOTHING;

